design.prefetcher_source:
#include <cstdint>
#include "address.h"
#include "modules.h"

struct gen_default_s1 : public champsim::modules::prefetcher {
  using prefetcher::prefetcher;

  // State for the stride prefetcher
  champsim::block_number last_demand_block = champsim::block_number{0}; // Stores the block address of the last demand access
  bool has_last_demand = false;                                          // Flag to indicate if last_demand_block is valid
  champsim::block_number::difference_type current_stride = 0;           // The stride detected between consecutive demand accesses
  int stride_consecutive_count = 0;                                      // How many times the current_stride has been observed consecutively

  uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
    // Only train on demand accesses (LOAD, RFO, WRITE). Prefetches should not influence training.
    if (type == access_type::PREFETCH) {
      return metadata_in;
    }

    champsim::block_number current_block{addr};

    if (has_last_demand) {
      // Calculate the stride between the last demand access and the current demand access
      champsim::block_number::difference_type detected_stride = champsim::offset(last_demand_block, current_block);

      if (detected_stride == 0) {
        // The same block was accessed again, or no movement. Reset stride detection.
        stride_consecutive_count = 0;
        current_stride = 0; // Reset current_stride to indicate no active stride
      } else {
        if (detected_stride == current_stride) {
          // The same stride was detected again, increase confidence
          stride_consecutive_count++;
        } else {
          // A new stride was detected, reset confidence and update the current_stride
          current_stride = detected_stride;
          stride_consecutive_count = 1; // This is the first occurrence of this new stride
        }

        // If we've seen the same stride at least twice (meaning three consecutive blocks
        // have formed a consistent stride: A, A+S, A+2S), then we are confident to prefetch.
        // On the A+2S access, stride_consecutive_count becomes 2, triggering the prefetch for A+3S.
        if (stride_consecutive_count >= 2) {
          champsim::block_number pf_blk = current_block + current_stride;
          // Issue a prefetch for the next block in the detected stride pattern
          prefetch_line(champsim::address{pf_blk}, true, metadata_in);
        }
      }
    } else {
      // This is the very first demand access observed. Initialize the state.
      has_last_demand = true;
    }

    // Update last_demand_block for the next access to this cache
    last_demand_block = current_block;

    return metadata_in;
  }

  uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
    // This prefetcher does not require any action or training on cache fill events.
    return metadata_in;
  }
};

reference.prefetcher_source:
#include <cstdint>
#include "address.h"
#include "modules.h"
#include <vector>
#include <algorithm>

// Define the maximum number of entries in our IP-based stride history table.
// A small number of entries is chosen to keep the table manageable and fast to search.
constexpr uint32_t MAX_STRIDE_TABLE_ENTRIES = 8;

struct gen_default_s3 : public champsim::modules::prefetcher {
  using prefetcher::prefetcher;

  // Structure to store per-Instruction Pointer (IP) history for stride detection.
  struct StrideEntry {
    champsim::address ip;                     // The Instruction Pointer identifying the access stream.
    champsim::block_number last_block;        // The last memory block address accessed by this IP.
    champsim::block_number::difference_type last_stride; // The last detected stride for this IP.
    uint8_t confidence;                       // Confidence level in the `last_stride`.
  };

  // A vector acts as a small, fully-associative cache for StrideEntry objects.
  // Entries are evicted in a FIFO manner when the table is full.
  std::vector<StrideEntry> stride_history_table;

  uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
    // Convert the accessed address to a block_number for arithmetic operations.
    champsim::block_number current_block{addr};

    // This prefetcher trains only on demand accesses (LOAD or STORE).
    // It ignores prefetches hitting or missing in the cache to avoid self-training loops.
    bool is_demand_access = (type == access_type::LOAD || type == access_type::STORE);

    if (is_demand_access) {
      // Search for an existing entry for the current Instruction Pointer (IP).
      auto it = std::find_if(stride_history_table.begin(), stride_history_table.end(),
                             [&](const StrideEntry& entry) { return entry.ip == ip; });

      if (it != stride_history_table.end()) { // IP found in the history table.
        // Calculate the current stride as the difference between the last and current block.
        champsim::block_number::difference_type current_stride = champsim::offset(it->last_block, current_block);

        if (current_stride != 0) { // Only consider non-zero strides to detect movement.
          if (current_stride == it->last_stride) {
            // The stride is consistent; increase confidence (capped to prevent overflow and overly aggressive prefetching).
            if (it->confidence < 3) { // Max confidence of 3, for example.
              it->confidence++;
            }
          } else {
            // Stride has changed; reset confidence and update to the new stride.
            it->confidence = 1;
            it->last_stride = current_stride;
          }

          // If confidence is sufficiently high, issue a prefetch.
          // The "at most one prefetch per access" constraint is met because
          // `prefetch_line` is called at most once per `prefetcher_cache_operate` invocation.
          if (it->confidence >= 2) { // Prefetch if the same stride has been observed at least twice.
            champsim::block_number prefetch_blk = current_block + it->last_stride;
            prefetch_line(champsim::address{prefetch_blk}, true, metadata_in);
          }
        } else { // `current_stride == 0`: The same block was accessed again.
          // Reset confidence and last_stride as the stream is not progressing with a consistent stride.
          it->confidence = 0;
          it->last_stride = 0;
        }

        // Update the last_block for this IP for the next access.
        it->last_block = current_block;

      } else { // IP not found; add a new entry to the history table.
        // If the table is full, evict the oldest entry (FIFO replacement policy).
        if (stride_history_table.size() >= MAX_STRIDE_TABLE_ENTRIES) {
          stride_history_table.erase(stride_history_table.begin());
        }
        // Add the new entry, initializing stride and confidence to zero.
        stride_history_table.push_back({ip, current_block, 0, 0});
      }
    }

    return metadata_in;
  }

  uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
    // This prefetcher does not require cache fill events for its training or prefetching logic.
    return metadata_in;
  }
};
